import{_ as d,o as r,c as a,ag as e}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"0-3岁婴幼儿健康照护指南","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/infant-care/0-3-guide.md","filePath":"topics/infant-care/0-3-guide.md"}'),o={name:"topics/infant-care/0-3-guide.md"};function h(l,t,i,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_0-3岁婴幼儿健康照护指南" tabindex="-1">0-3岁婴幼儿健康照护指南 <a class="header-anchor" href="#_0-3岁婴幼儿健康照护指南" aria-label="Permalink to &quot;0-3岁婴幼儿健康照护指南&quot;">​</a></h1><blockquote><p>整理自国家卫健委 WS/T 678-2020《婴幼儿辅食添加营养指南》、《婴幼儿早期发展服务指南》2025、《婴幼儿营养喂养评估指南》2025</p></blockquote><hr><h2 id="一、屏幕管控-原文明确" tabindex="-1">一、屏幕管控（原文明确） <a class="header-anchor" href="#一、屏幕管控-原文明确" aria-label="Permalink to &quot;一、屏幕管控（原文明确）&quot;">​</a></h2><p><strong>《婴幼儿早期发展服务指南》2025 原文：</strong></p><blockquote><p>0～3岁婴幼儿应当不接触任何形式的视屏类产品</p></blockquote><table tabindex="0"><thead><tr><th>月龄</th><th>要求</th></tr></thead><tbody><tr><td>0-3岁</td><td><strong>全面禁止</strong>任何屏幕（电视、手机、平板）</td></tr></tbody></table><p>正确替代：积木、绘本、户外活动。</p><hr><h2 id="二、辅食添加-原文核心" tabindex="-1">二、辅食添加（原文核心） <a class="header-anchor" href="#二、辅食添加-原文核心" aria-label="Permalink to &quot;二、辅食添加（原文核心）&quot;">​</a></h2><h3 id="_2-1-喂养时机" tabindex="-1">2.1 喂养时机 <a class="header-anchor" href="#_2-1-喂养时机" aria-label="Permalink to &quot;2.1 喂养时机&quot;">​</a></h3><table tabindex="0"><thead><tr><th>月龄</th><th>建议</th></tr></thead><tbody><tr><td><strong>满6月龄</strong></td><td>开始添加辅食（不早于4月龄，不晚于8月龄）</td></tr><tr><td>继续母乳喂养</td><td>辅食添加不早于4月龄，不影响母乳喂养</td></tr></tbody></table><h3 id="_2-2-辅食添加原则" tabindex="-1">2.2 辅食添加原则 <a class="header-anchor" href="#_2-2-辅食添加原则" aria-label="Permalink to &quot;2.2 辅食添加原则&quot;">​</a></h3><p><strong>WS/T 678-2020 原文：</strong></p><blockquote><p>首先补充含铁丰富、易消化且不易引起过敏的食物</p></blockquote><p><strong>具体顺序：</strong></p><ol><li><strong>高铁米粉 / 肉泥 / 肝泥</strong> ← 第一口必须是这些，不是米汤</li><li>根茎类蔬菜泥（南瓜、土豆、胡萝卜）</li><li>叶菜泥</li><li>蛋黄（⚠️ 牛奶蛋白过敏宝宝见本节第三部分）</li><li>禽肉、鱼泥</li></ol><p><strong>添加原则：</strong></p><ul><li>由稀到稠</li><li>由一种到多种</li><li>每次加一种新食物，观察 <strong>3-5天</strong>，不过敏再换下一种</li><li>生病时不添加新食物</li></ul><h3 id="_2-3-12月龄内禁忌" tabindex="-1">2.3 12月龄内禁忌 <a class="header-anchor" href="#_2-3-12月龄内禁忌" aria-label="Permalink to &quot;2.3 12月龄内禁忌&quot;">​</a></h3><p><strong>WS/T 678-2020 原文：</strong></p><blockquote><p>12月龄内不宜添加盐、糖及刺激性调味品</p></blockquote><p>禁止：盐、糖、酱油、蜂蜜、整颗坚果、整颗葡萄</p><hr><h2 id="三、牛奶蛋白过敏宝宝的辅食-推导建议" tabindex="-1">三、牛奶蛋白过敏宝宝的辅食（推导建议） <a class="header-anchor" href="#三、牛奶蛋白过敏宝宝的辅食-推导建议" aria-label="Permalink to &quot;三、牛奶蛋白过敏宝宝的辅食（推导建议）&quot;">​</a></h2><blockquote><p>⚠️ 以下内容结合指南原则推导，医疗决策以儿科医生为准</p></blockquote><h3 id="_3-1-辅食添加原则" tabindex="-1">3.1 辅食添加原则 <a class="header-anchor" href="#_3-1-辅食添加原则" aria-label="Permalink to &quot;3.1 辅食添加原则&quot;">​</a></h3><p>牛奶蛋白过敏宝宝的辅食<strong>不是&quot;不能加&quot;，而是&quot;加慢一点、观察仔细&quot;</strong>。</p><p>每次只加一种新食物，观察3-5天，有以下反应即暂停：</p><ul><li>湿疹加重</li><li>嘴周红肿</li><li>呕吐/腹泻</li></ul><h3 id="_3-2-肉类添加顺序" tabindex="-1">3.2 肉类添加顺序 <a class="header-anchor" href="#_3-2-肉类添加顺序" aria-label="Permalink to &quot;3.2 肉类添加顺序&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>肉类</th><th>原因</th></tr></thead><tbody><tr><td>✅ 首先</td><td><strong>猪肉</strong>（里脊）</td><td>过敏风险最低</td></tr><tr><td>✅ 其次</td><td><strong>鸡胸肉</strong></td><td>禽类蛋白和牛奶蛋白交叉过敏概率约5-10%，观察</td></tr><tr><td>⚠️ 稍后</td><td>牛肉/羊肉</td><td>稍后尝试</td></tr><tr><td>❌ 1岁后</td><td>奶酪/酸奶/全蛋</td><td>1岁以后再试</td></tr></tbody></table><h3 id="_3-3-蛋黄说明" tabindex="-1">3.3 蛋黄说明 <a class="header-anchor" href="#_3-3-蛋黄说明" aria-label="Permalink to &quot;3.3 蛋黄说明&quot;">​</a></h3><p>⚠️ <strong>重要纠正：</strong><br> WS/T 678-2020 原文将蛋黄列为6-8月龄首选食物之一，<strong>并非推迟到9个月</strong>。牛奶蛋白过敏宝宝是否推迟蛋黄添加，应<strong>咨询儿科或过敏专科医生</strong>，不宜自行决定。</p><hr><h2 id="四、8月龄发育指标" tabindex="-1">四、8月龄发育指标 <a class="header-anchor" href="#四、8月龄发育指标" aria-label="Permalink to &quot;四、8月龄发育指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>8个月应该会的</th></tr></thead><tbody><tr><td>大运动</td><td>独坐稳、部分开始爬、扶站</td></tr><tr><td>精细运动</td><td>换手玩玩具、捏小东西</td></tr><tr><td>语言</td><td>发出无意识的&quot;baba/dada&quot;音</td></tr><tr><td>社交</td><td>认生、认妈妈、对镜子感兴趣</td></tr></tbody></table><blockquote><p>每个孩子节奏不同，在范围内即正常，不与他人攀比。</p></blockquote><h3 id="_8月龄喂养参考" tabindex="-1">8月龄喂养参考 <a class="header-anchor" href="#_8月龄喂养参考" aria-label="Permalink to &quot;8月龄喂养参考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>配方奶</td><td>每天600-800ml，分4次</td></tr><tr><td>辅食</td><td>每天2顿 + 手指食物</td></tr><tr><td>重点</td><td><strong>每天一顿红肉（补铁）</strong>，猪/牛/羊里脊均可</td></tr><tr><td>禁忌</td><td>整颗坚果、整颗葡萄、蜂蜜（1岁内）</td></tr></tbody></table><hr><h2 id="五、贫血筛查" tabindex="-1">五、贫血筛查 <a class="header-anchor" href="#五、贫血筛查" aria-label="Permalink to &quot;五、贫血筛查&quot;">​</a></h2><p><strong>《婴幼儿营养喂养评估指南》2025 规定节点：</strong></p><ul><li>满6月龄（必查）</li><li>满24月龄（必查）</li><li>满30月龄（必查）</li></ul><p><strong>过敏高风险宝宝：</strong> 可在8月龄主动要求加查。</p><hr><h2 id="六、睡眠安全" tabindex="-1">六、睡眠安全 <a class="header-anchor" href="#六、睡眠安全" aria-label="Permalink to &quot;六、睡眠安全&quot;">​</a></h2><p><strong>仰卧睡姿：</strong> 1岁内婴儿必须仰卧睡觉，趴睡和侧睡大幅增加婴儿猝死综合征（SIDS）风险。</p><p>婴儿床要求：</p><ul><li>不放枕头、厚被子、毛绒玩具</li><li>喝奶后睡着应放回婴儿床</li><li>不在沙发、座椅、怀里长时间睡</li></ul><hr><h2 id="七、发烧处理" tabindex="-1">七、发烧处理 <a class="header-anchor" href="#七、发烧处理" aria-label="Permalink to &quot;七、发烧处理&quot;">​</a></h2><p><strong>绝对禁止：捂汗</strong></p><table tabindex="0"><thead><tr><th>体温</th><th>处理方式</th></tr></thead><tbody><tr><td>38.5℃以下</td><td>解开衣服，温水擦浴（额头/脖子/腋下/大腿根），多喝奶/水</td></tr><tr><td>38.5℃以上</td><td>遵医嘱用退烧药，不自行加量</td></tr></tbody></table><p><strong>立刻去医院：</strong> 精神差、嗜睡、抽搐、呕吐、呼吸急促。</p><hr><h2 id="八、体检节点" tabindex="-1">八、体检节点 <a class="header-anchor" href="#八、体检节点" aria-label="Permalink to &quot;八、体检节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>月龄</th><th>必须完成</th></tr></thead><tbody><tr><td>1月龄</td><td>体检</td></tr><tr><td>3月龄</td><td>体检</td></tr><tr><td>6月龄</td><td>体检 + <strong>血红蛋白（必查）</strong></td></tr><tr><td>8月龄</td><td>体检（过敏宝宝可主动加查血常规）</td></tr><tr><td>12月龄</td><td>体检</td></tr><tr><td>18月龄</td><td>体检 + <strong>语言发育重点筛查</strong></td></tr><tr><td>24月龄</td><td>体检 + 血红蛋白</td></tr><tr><td>30月龄</td><td>体检 + 血红蛋白</td></tr><tr><td>36月龄</td><td>体检</td></tr></tbody></table><hr><h2 id="九、回应性照护" tabindex="-1">九、回应性照护 <a class="header-anchor" href="#九、回应性照护" aria-label="Permalink to &quot;九、回应性照护&quot;">​</a></h2><table tabindex="0"><thead><tr><th>月龄</th><th>回应方式</th></tr></thead><tbody><tr><td>0-3个月</td><td>哭了立刻回应——饿了喂、困了哄、尿了换。多抱不惯坏，建立安全感。</td></tr><tr><td>4-12个月</td><td>先观察原因，轻声拍拍让其学会自我平静。无理取闹不纵容。</td></tr><tr><td>1-3岁</td><td>先共情&quot;妈妈知道你难过&quot;，再讲道理，最后解决问题。不打骂、不冷暴力。</td></tr></tbody></table><hr><h2 id="十、常见发育里程碑" tabindex="-1">十、常见发育里程碑 <a class="header-anchor" href="#十、常见发育里程碑" aria-label="Permalink to &quot;十、常见发育里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>月龄</th><th>大运动</th><th>喂养节奏</th></tr></thead><tbody><tr><td>1个月</td><td>短暂抬头45°</td><td>按需，每天8-10次</td></tr><tr><td>2个月</td><td>抬头更稳</td><td>睡眠周期约40分钟</td></tr><tr><td>3个月</td><td>稳定抬头90°</td><td>间隔3-4小时，夜间可睡6-8小时</td></tr><tr><td>6-12个月</td><td>坐、爬、站</td><td>辅食加入，奶+辅食并进</td></tr><tr><td>1-2岁</td><td>走、跑、跳</td><td>三餐+两加餐</td></tr><tr><td>2-3岁</td><td>跑跳自如</td><td>规律三餐，不追着喂</td></tr></tbody></table><hr><p><em>最后更新：2026-06-17</em></p>',66)])])}const p=d(o,[["render",h]]);export{c as __pageData,p as default};
